151	        owner.setTelephone(this.telephoneNormalizer.normalize(owner.getTelephone()));
152	        owner.setEmail(this.emailNormalizer.normalize(owner.getEmail()));
153	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
154	        owner.setRegistrationDate(this.businessDayResolver.toBusinessDay(effectiveDate));
155	        long ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(owner.getRegistrationDate());
156	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
157	            throw new OwnerDailyRegistrationLimitExceededException(owner.getRegistrationDate(), MAX_OWNERS_PER_DAY);
158	        }
159	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
160	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
161	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
162	        }
163	        if (owner.getEmail() != null && !this.clinicService.findOwnersByEmail(owner.getEmail()).isEmpty()) {
164	            throw new DuplicateOwnerEmailException(owner.getEmail());
165	        }
166	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
167	            throw new OwnerCityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
168	        }
169	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
170	            this.clinicService.joinHousehold(owner);
171	        } else if (!this.clinicService.findOwnersInSameHousehold(owner.getLastName(), owner.getAddress()).isEmpty()) {
172	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
173	        }
174	        this.clinicService.saveOwner(owner);
