18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.controller.DuplicateOwnerEmailException;
33	import org.springframework.samples.petclinic.rest.controller.DuplicateOwnerHouseholdException;
34	import org.springframework.samples.petclinic.rest.controller.DuplicateOwnerTelephoneException;
35	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
36	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
37	import org.springframework.samples.petclinic.rest.controller.MissingOwnerFieldsException;
38	import org.springframework.samples.petclinic.rest.controller.OwnerCityCapacityExceededException;
39	import org.springframework.samples.petclinic.rest.controller.OwnerDailyRegistrationLimitExceededException;
40	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
41	import org.springframework.security.access.AccessDeniedException;
42	import org.springframework.validation.BindingResult;
43	import org.springframework.validation.FieldError;
44	import org.springframework.web.bind.MethodArgumentNotValidException;
45	import org.springframework.web.bind.annotation.ControllerAdvice;
46	import org.springframework.web.bind.annotation.ExceptionHandler;
47	import org.springframework.web.bind.annotation.ResponseBody;
48	
49	/**
50	 * Global Exception handler for REST controllers.
51	 * <p>
52	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
53	 *
54	 * @author Vitaliy Fedoriv
55	 * @author Alexander Dudkin
56	 */
57	@ControllerAdvice
58	public class ExceptionControllerAdvice {
59	
60	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
61	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
62	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
63	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
64	
65	    /**
66	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
67	     * class.
68	     *
69	     * @param e     Object referring to the thrown exception.
70	     * @param status HTTP response status.
71	     * @param url URL request.
72	     */
73	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
74	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
75	        problemDetail.setType(URI.create(url.toString()));
76	        problemDetail.setTitle(e.getClass().getSimpleName());
77	        problemDetail.setDetail(detail);
78	        problemDetail.setProperty("timestamp", Instant.now());
79	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
80	        return problemDetail;
81	    }
82	
83	    /**
84	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
85	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
86	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
87	     * would catch it and report an authorization failure as a 500.
88	     *
89	     * @param e The {@link AccessDeniedException} to propagate
90	     * @throws AccessDeniedException always
91	     */
92	    @ExceptionHandler(AccessDeniedException.class)
93	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
94	        throw e;
95	    }
96	
97	    /**
98	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
99	     *
100	     * @param e The {@link Exception} to be handled
101	     * @param request {@link HttpServletRequest} object referring to the current request.
102	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
103	     */
104	    @ExceptionHandler(Exception.class)
105	    @ResponseBody
106	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
107	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
108	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
109	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
110	        return ResponseEntity.status(status).body(detail);
111	    }
112	
113	    /**
114	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
115	     * method returns a 404 Not Found status if an entity does not exist.
116	     *
117	     * @param e The {@link DataIntegrityViolationException} to be handled
118	     * @param request {@link HttpServletRequest} object referring to the current request.
119	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
120	     */
121	    @ExceptionHandler(DataIntegrityViolationException.class)
122	    @ResponseBody
123	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
124	        logger.warn("Data integrity violation at {} {}: {}",
125	            request.getMethod(),
126	            request.getRequestURI(),
127	            e.getMessage());
128	        logger.debug("Data integrity violation stacktrace", e);
129	        HttpStatus status = HttpStatus.NOT_FOUND;
130	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
131	        return ResponseEntity.status(status).body(detail);
132	    }
133	
134	    /**
135	     * Handles exception thrown by Bean Validation on controller methods parameters
136	     *
137	     * @param e The {@link MethodArgumentNotValidException} to be handled
138	     * @param request {@link HttpServletRequest} object referring to the current request.
139	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
140	     */
141	    @ExceptionHandler(MethodArgumentNotValidException.class)
142	    @ResponseBody
143	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
144	        HttpStatus status = HttpStatus.BAD_REQUEST;
145	        BindingErrorsResponse errors = new BindingErrorsResponse();
146	        BindingResult bindingResult = e.getBindingResult();
147	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
148	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
149	            .map(FieldError::getField)
150	            .distinct()
151	            .toList());
152	        if (bindingResult.hasErrors()) {
153	            errors.addAllErrors(bindingResult);
154	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
155	                .map(fieldError -> {
156	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
157	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
158	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
159	                        fieldError.getField(),
160	                        defaultMessage,
161	                        rejectedValue);
162	                    return new ValidationMessageDto(message)
163	                        .putAdditionalProperty("field", fieldError.getField())
164	                        .putAdditionalProperty("rejectedValue", rejectedValue)
165	                        .putAdditionalProperty("defaultMessage", defaultMessage);
166	                })
167	                .toList();
168	            logger.debug("Validation error at {} {}: {}",
169	                request.getMethod(),
170	                request.getRequestURI(),
171	                bindingResult.getFieldErrors());
172	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
173	            return ResponseEntity.status(status).body(detail);
174	        }
175	        return ResponseEntity.status(status).body(detail);
176	    }
177	
178	    /**
179	     * Handles {@link MissingOwnerFieldsException} raised when an owner request omits or
180	     * leaves blank one or more required fields. Returns a 400 Bad Request whose
181	     * {@code errors} array names each offending field.
182	     *
183	     * @param e The {@link MissingOwnerFieldsException} to be handled
184	     * @param request {@link HttpServletRequest} object referring to the current request.
185	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
186	     */
187	    @ExceptionHandler(MissingOwnerFieldsException.class)
188	    @ResponseBody
189	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
190	        HttpStatus status = HttpStatus.BAD_REQUEST;
191	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
192	        detail.setProperty("errors", e.getMissingFields());
193	        return ResponseEntity.status(status).body(detail);
194	    }
195	
196	    /**
197	     * Handles {@link InvalidTelephoneException} raised when an owner request supplies a
198	     * telephone number that cannot form a valid E.164 number — either the wrong total digit
199	     * count or a national number whose length does not match its country code. Returns a 400
200	     * Bad Request whose {@code errors} array names the {@code telephone} field.
201	     *
202	     * @param e The {@link InvalidTelephoneException} to be handled
203	     * @param request {@link HttpServletRequest} object referring to the current request.
204	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
205	     */
206	    @ExceptionHandler(InvalidTelephoneException.class)
207	    @ResponseBody
208	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
209	        HttpStatus status = HttpStatus.BAD_REQUEST;
210	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
211	        detail.setProperty("errors", List.of("telephone"));
212	        return ResponseEntity.status(status).body(detail);
213	    }
214	
215	    /**
216	     * Handles {@link InvalidEmailException} raised when an owner request supplies an email
217	     * address that is not syntactically valid. Returns a 400 Bad Request whose
218	     * {@code errors} array names the {@code email} field.
219	     *
220	     * @param e The {@link InvalidEmailException} to be handled
221	     * @param request {@link HttpServletRequest} object referring to the current request.
222	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
223	     */
224	    @ExceptionHandler(InvalidEmailException.class)
225	    @ResponseBody
226	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
227	        HttpStatus status = HttpStatus.BAD_REQUEST;
228	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
229	        detail.setProperty("errors", List.of("email"));
230	        return ResponseEntity.status(status).body(detail);
231	    }
232	
233	    /**
234	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner request supplies a
235	     * telephone number whose normalized value is already used by an existing owner. Returns a
236	     * 409 Conflict whose {@code errors} array names the {@code telephone} field.
237	     *
238	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
239	     * @param request {@link HttpServletRequest} object referring to the current request.
240	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
241	     */
242	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
243	    @ResponseBody
244	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
245	        HttpStatus status = HttpStatus.CONFLICT;
246	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
247	        detail.setProperty("errors", List.of("telephone"));
248	        return ResponseEntity.status(status).body(detail);
249	    }
250	
251	    /**
252	     * Handles {@link DuplicateOwnerEmailException} raised when an owner request supplies an
253	     * email address whose lower-cased value is already used by an existing owner. Returns a
254	     * 409 Conflict whose {@code errors} array names the {@code email} field.
255	     *
256	     * @param e The {@link DuplicateOwnerEmailException} to be handled
257	     * @param request {@link HttpServletRequest} object referring to the current request.
258	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
259	     */
260	    @ExceptionHandler(DuplicateOwnerEmailException.class)
261	    @ResponseBody
262	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerEmailException(DuplicateOwnerEmailException e, HttpServletRequest request) {
263	        HttpStatus status = HttpStatus.CONFLICT;
264	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
265	        detail.setProperty("errors", List.of("email"));
266	        return ResponseEntity.status(status).body(detail);
267	    }
268	
269	    /**
270	     * Handles {@link DuplicateOwnerHouseholdException} raised when an owner request would
271	     * create an owner whose last name and address (compared case-insensitively with
272	     * collapsed whitespace) already belong to another owner, without opting in to a shared
273	     * household. Returns a 409 Conflict whose {@code errors} array names the {@code lastName}
274	     * and {@code address} fields.
275	     *
276	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
277	     * @param request {@link HttpServletRequest} object referring to the current request.
278	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
279	     */
280	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
281	    @ResponseBody
282	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
283	        HttpStatus status = HttpStatus.CONFLICT;
284	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
285	        detail.setProperty("errors", List.of("lastName", "address"));
286	        return ResponseEntity.status(status).body(detail);
287	    }
288	
289	    /**
290	     * Handles {@link OwnerCityCapacityExceededException} raised when an owner request would
291	     * create an owner in a city that already holds the maximum permitted number of owners.
292	     * Returns a 409 Conflict whose {@code errors} array names the {@code city} field.
293	     *
294	     * @param e The {@link OwnerCityCapacityExceededException} to be handled
295	     * @param request {@link HttpServletRequest} object referring to the current request.
296	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
297	     */
298	    @ExceptionHandler(OwnerCityCapacityExceededException.class)
299	    @ResponseBody
